5	/**
6	 * A simple model of a mouse.
7	 * Mice can age, move, contract diseases, eat plants and die. 
8	 *
9	 * @version 2022.03.02
10	 */
11	public class Mouse extends Animal
12	{
13	    // Characteristics shared by all Mice (class variables).
14	
15	    // The age at which a Mouse can start to breed.
16	    private static final int BREEDING_AGE = 5;
17	    // The age to which a Mouse can live.
18	    private static final int MAX_AGE = 40;
19	    // The likelihood of a Mouse breeding.
20	    private static final double BREEDING_PROBABILITY = 0.5;
21	    // The maximum number of births.
22	    private static final int MAX_LITTER_SIZE = 4;
23	    // A shared random number generator to control breeding.
24	    private static final Random rand = Randomizer.getRandom();
25	    // The mouse's food level which is increased by eating prey.
26	    private static final int MAX_FOOD_LEVEL = 9;
27	    // The food value of a single mouse.
28	    private static final int FOOD_VALUE = 2;
29	    // A set of organisms that a mouse consumes
30	    private static final Set<Class> DIET = new HashSet<>(Arrays.asList(Grass.class));
31	
32	    protected double BREEDING_AGE() { return BREEDING_AGE; }
33	    protected int MAX_LITTER_SIZE() { return MAX_LITTER_SIZE; }
34	    protected double BREEDING_PROBABILITY() { return BREEDING_PROBABILITY; }
35	    
36	    protected int MAX_AGE() { return MAX_AGE; }
37	    protected int MAX_FOOD_LEVEL() { return MAX_FOOD_LEVEL; }
38	    protected int FOOD_VALUE() { return FOOD_VALUE; }
39	    protected Set<Class> DIET() { return DIET; }
40	
41	    
42	    /**
43	     * Create a new Mouse. A Mouse may be created with age
44	     * zero (a new born) or with a random age.
45	     * @param randomAge If true, the Mouse will have a random age.
46	     * @param field The field currently occupied.
47	     * @param location The location within the field.
48	     * @param sex The gender of the mouse.
49	     */
50	    public Mouse(boolean randomAge, Field field, Location location, Gender sex)
51	    {
52	        super(field, location, randomAge, sex);
53	        this.isNocturnal = false;
54	    }
55	
56	
57	    /**
58	     * Check whether this mouse is to give birth at this step.
59	     * New births will be made into free adjacent locations.
60	     * @param newMouses A list to return newly born mice.
61	     * @param environment The environment that mouse resides in. 
62	     */
63	    protected void giveBirth(List<Actor> newMouses, Environment environment)
64	    {
65	        // New Mouses are born into adjacent locations.
66	        // Get a list of adjacent free locations.
67	        Field field = getField();
68	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
69	        int births = breed();
70	        for(int b = 0; b < births && free.size() > 0; b++) {
71	            Location loc = free.remove(0);
72	            Mouse young = new Mouse(false, field, loc, sex);
73	            newMouses.add(young);
74	        }
75	    }
76	
77	
78	}
