26	    private static final Random rand = Randomizer.getRandom();
27	    // The food value of a single eagle.
28	    private static final int FOOD_VALUE = 5;
29	    // A set of organisms that a eagle consumes
30	    private static final Set<Class> DIET = new HashSet<>(Arrays.asList(Deer.class, Coyote.class, Mouse.class));
31	
32	    // Implementing abstract methods to return fields to be used by the superclass
33	    protected double BREEDING_AGE() { return BREEDING_AGE; }
34	    protected int MAX_LITTER_SIZE() { return MAX_LITTER_SIZE; }
35	    protected double BREEDING_PROBABILITY() { return BREEDING_PROBABILITY; }
