41	    /**
42	     * Create a eagle. A eagle can be created as a new born (age zero
43	     * and not hungry) or with a random age and food level.
44	     * @param randomAge If true, the eagle will have random age and hunger level.
45	     * @param field The field currently occupied.
46	     * @param location The location within the field.
47	     * @param sex The gender of the eagle.
48	     */
49	    public Eagle(boolean randomAge, Field field, Location location, Gender sex)
50	    {
51	        super(field, location,randomAge,sex);
52	        this.isNocturnal = false;
53	    }
54	
55	    
56	    /**
57	     * Check whether this eagle is to give birth at this step.
58	     * New births will be made into free adjacent locations.
59	     * @param newEagles A list to return newly born Eagles.
60	     * @param environment The environment that the eagle resides in. 
61	     */
62	    protected void giveBirth(List<Actor> newEagles, Environment environment)
63	    {
64	        // New Eagles are born into adjacent locations.
