3	/**
4	 * A simple model of a hunter. 
5	 * Hunters hunt all of the species in the simulation.
6	 * @version 2022.03.02
7	 */
8	public class Hunter implements Actor
9	{
10	    private static boolean alive;
11	    private Field field;
12	    private Location location;
13	
14	    private Random rand = Randomizer.getRandom();
15	    // A hunter hunts every species. 
16	    private static final Set<Class> DIET = new HashSet<>(Arrays.asList(Deer.class, Mouse.class, Wolf.class, Coyote.class, Eagle.class));
17	
18	
19	    /**
20	     * Creates a new hunter.
21	     * @param field The field currently occupied.
22	     * @param location  The location within the field.
23	     * @param environment The environment that the hunter resides in. 
24	     */
25	    public Hunter(Field field, Location location, Environment environment)
26	    {
27	        alive = true;
28	        this.field = field;
29	        setLocation(location);
30	    }
31	
32	    /**
33	     * Returns true if the hunter is alive. 
34	     */
35	    public boolean isAlive() 
36	    {
37	        return alive;
38	    }
39	
40	    /**
41	     * Makes the hunter hunt for nearby animals. 
42	     * @param environment The environment that the hunter resides in. 
43	     * @param newActors A list to receive new actors. 
44	     */
45	    public void act(List<Actor> newActors, Environment environment)
46	    {
47	        if(isAlive()) {
48	            Location newLocation = findPrey();
49	            if(newLocation == null) {
50	                // No animals found - try to move to a free location.
51	                newLocation = field.freeAdjacentLocation(location);
52	            }
53	            List<Location> adjacentGrassSpots = field.adjacentLocationsWithSpecies(location, Grass.class);
54	
55	            // See if it was possible to move.
56	            if(newLocation != null) {
57	                setLocation(newLocation);
58	            }
59	            else if (adjacentGrassSpots.size() > 0) {
60	                field.clear(location);
61	                setLocation(adjacentGrassSpots.get(rand.nextInt(adjacentGrassSpots.size())));
62	            }
63	
64	        }
65	    }
66	
67	    /**
68	     * Place the hunter at the new location in the given field.
69	     * @param newLocation The hunter's new location.
70	     */
71	    protected void setLocation(Location newLocation)
72	    {
73	        if(location != null) {
74	            field.clear(location);
75	        }
76	        location = newLocation;
77	        field.place(this, newLocation);
78	    }
79	
80	
81	    /**
82	     * Look for animals adjacent to the current location.
83	     * Only the first live animal is killed.
84	     * @return Location Where an animal was found, or null if it wasn't.
85	     */
86	    private Location findPrey()
87	    {
88	        Field field = this.field;
89	        List<Location> adjacent = field.adjacentLocations(location);
90	        Iterator<Location> it = adjacent.iterator();
91	        while(it.hasNext()) {
92	            Location where = it.next();
93	            Object animal = field.getObjectAt(where);
94	            if(animal != null && DIET.contains(animal.getClass())) {
95	                Animal food = (Animal) animal;
96	                if(food.isAlive()) {
97	                    food.setDead();
98	                    return where;
99	                }
100	                return where;
101	            }
102	        }
103	        return null;
104	    }
105	}
