    protected abstract int MAX_LITTER_SIZE();
    protected abstract double BREEDING_PROBABILITY();
    protected abstract int MAX_AGE();
    protected abstract int MAX_FOOD_LEVEL();
    protected abstract Set<Class> DIET();


