            this.age = rand.nextInt(MAX_AGE());
            foodLevel = rand.nextInt(MAX_FOOD_LEVEL());
        }
        else {
            this.age = 0;
            foodLevel = MAX_FOOD_LEVEL();
        }
        diseaseManager.processRandomContraction();
    }

